import ast, inspect, sys
from pathlib import Path

# Ensure local matplotlib is imported
lib_path = Path('/testbed/lib')
if str(lib_path) not in sys.path:
    sys.path.insert(0, str(lib_path))

from matplotlib.streamplot import _integrate_rk12
from qa_instances_eval.matplotlib_qa.streamplot_integrate_rk12_def_use_pairs.files.tests.qa.streamplot_integrate_rk12_def_use_pairs_test import TestStreamplotIntegrateRk12DefUsePairsQA

TRACKED = {
    'broken_streamlines', 'dmap', 'ds', 'dx1', 'dx2', 'dy1', 'dy2', 'error', 'f',
    'k1x', 'k1y', 'k2x', 'k2y', 'maxds', 'maxerror', 'maxlength', 'nx', 'ny',
    'stotal', 'x0', 'xi', 'xyf_traj', 'y0', 'yi'
}

source_file = Path(inspect.getsourcefile(_integrate_rk12))
source_lines, start_line = inspect.getsourcelines(_integrate_rk12)
source = ''.join(source_lines)

# Build per-line read/def sets from AST using function-local line numbers -> absolute line numbers
func_ast = ast.parse(source).body[0]
line_reads = {}
line_defs = {}

class Visitor(ast.NodeVisitor):
    def add_read(self, name, lineno):
        if name in TRACKED:
            line_reads.setdefault(lineno, set()).add(name)
    def add_def(self, name, lineno):
        if name in TRACKED:
            line_defs.setdefault(lineno, set()).add(name)

    def visit_Name(self, node):
        if isinstance(node.ctx, ast.Load):
            self.add_read(node.id, node.lineno)
        elif isinstance(node.ctx, (ast.Store, ast.Del)):
            self.add_def(node.id, node.lineno)

    def visit_FunctionDef(self, node):
        # Skip parameters as defs per rules; just visit body
        for stmt in node.body:
            self.visit(stmt)

    def visit_AugAssign(self, node):
        # Process value reads normally; treat target only as definition for line-level convention.
        self.visit(node.value)
        for n in ast.walk(node.target):
            if isinstance(n, ast.Name):
                self.add_def(n.id, node.lineno)

    def visit_AnnAssign(self, node):
        if node.value:
            self.visit(node.value)
        for n in ast.walk(node.target):
            if isinstance(n, ast.Name):
                self.add_def(n.id, node.lineno)

Visitor().visit(func_ast)

# Convert local linenos to absolute
abs_reads = {start_line + ln - 1: names for ln, names in line_reads.items()}
abs_defs = {start_line + ln - 1: names for ln, names in line_defs.items()}

current_def = {v: None for v in TRACKED}
pairs = set()

code = _integrate_rk12.__code__
filename = str(source_file)

def tracer(frame, event, arg):
    if event == 'line' and frame.f_code is code and frame.f_code.co_filename == filename:
        lineno = frame.f_lineno
        # uses first
        for var in sorted(abs_reads.get(lineno, ())):
            d = current_def.get(var)
            if d is not None:
                pairs.add((var, d, lineno))
        # defs second
        for var in abs_defs.get(lineno, ()):
            current_def[var] = lineno
    return tracer

sys.settrace(tracer)
try:
    TestStreamplotIntegrateRk12DefUsePairsQA().test_streamplot_integrate_rk12_def_use_pairs_case()
finally:
    sys.settrace(None)

for p in sorted(pairs):
    print(p)
